 {'technology': 'python',
  'topic': 'professional-challenges',
  'kind': 'expert',
  'track': 'professional',
  'name': 'Sliding Window Maximum',
  'slug': 'py-pro-sliding-window-max',
  'description': 'Print the largest value in every window of k consecutive values. The values are generated, not typed: a[0] = seed, and '
                 'a[i] = (a[i-1] * 1103515245 + 12345) mod 2147483648 for i = 1..n-1. Use the values exactly as generated. Then take each '
                 'value mod 1000.',
  'input_format': 'One line: n k seed.',
  'output_format': 'Print one number: the sum of the maximums of all n - k + 1 windows.',
  'constraints': '1 ≤ k ≤ n ≤ 200,000. O(n·k) runs out of time; use a deque.',
  'examples': [{'input': '8 3 1', 'output': '4593'}],
  'language': 'python',
  'language_id': 71,
  'difficulty': 'Hard',
  'order': 9,
  'starter': "n, k, seed = map(int, input().split())\n# Generate the values, then print the sum of every window's maximum\n",
  'tests': [('8 3 1\n', '4593\n', False, 1),
            ('5 1 7\n', '1965\n', False, 1),
            ('5 5 3\n', '702\n', True, 1),
            ('200000 5000 11\n', '194805743\n', True, 3),
            ('120000 300 5\n', '119239404\n', True, 2)],
  'reference_source': 'from collections import deque\n'
                      'n, k, seed = map(int, input().split())\n'
                      'values = []\n'
                      'value = seed\n'
                      'for _ in range(n):\n'
                      '    values.append(value % 1000)\n'
                      '    value = (value * 1103515245 + 12345) % 2147483648\n'
                      'window = deque()\n'
                      'total = 0\n'
                      'for i, x in enumerate(values):\n'
                      '    while window and values[window[-1]] <= x:\n'
                      '        window.pop()\n'
                      '    window.append(i)\n'
                      '    if window[0] <= i - k:\n'
                      '        window.popleft()\n'
                      '    if i >= k - 1:\n'
                      '        total += values[window[0]]\n'
                      'print(total)\n'},
