                      'n, m = map(int, input().split())\n'
                      'after = [[] for _ in range(n + 1)]\n'
                      'indegree = [0] * (n + 1)\n'
                      'for _ in range(m):\n'
                      '    a, b = map(int, input().split())\n'
                      '    after[a].append(b)\n'
                      '    indegree[b] += 1\n'
                      'ready = [t for t in range(1, n + 1) if indegree[t] == 0]\n'
                      'heapq.heapify(ready)\n'
                      'order = []\n'
                      'while ready:\n'
                      '    t = heapq.heappop(ready)\n'
                      '    order.append(t)\n'
                      '    for nxt in after[t]:\n'
                      '        indegree[nxt] -= 1\n'
                      '        if indegree[nxt] == 0:\n'
                      '            heapq.heappush(ready, nxt)\n'
