 {'technology': 'python',
  'topic': 'professional-real-world-tasks',
  'kind': 'real_world',
  'track': 'professional',
  'name': 'Fix the Error Log Summary',
  'slug': 'py-pro-fix-log-summary',
  'description': 'Operations wants a summary of ERROR lines from a server log: each distinct message with how often it appeared. The '
                 "script misses errors written as 'error' or 'Error', keeps stray spaces, and sorts badly. Fix it.",
  'input_format': 'First line n. Next n lines: LEVEL message (LEVEL is any case; the message may have extra spaces at the ends).',
  'output_format': 'For each distinct ERROR message: count message, most frequent first, ties alphabetical. Print NO ERRORS if there are '
                   'none.',
  'constraints': '1 ≤ n ≤ 5,000.',
  'examples': [{'input': '4\nERROR disk full\nINFO started\nerror disk full\nError timeout', 'output': '2 disk full\n1 timeout'}],
  'language': 'python',
  'language_id': 71,
  'difficulty': 'Hard',
  'order': 13,
  'starter': 'n = int(input())\n'
             'counts = {}\n'
             'for _ in range(n):\n'
             '    level, message = input().split(" ", 1)\n'
             '    if level == "ERROR":\n'
             '        counts[message] = counts.get(message, 0) + 1\n'
             'for message in sorted(counts):\n'
             '    print(counts[message], message)\n',
  'tests': [('4\nERROR disk full\nINFO started\nerror disk full\nError timeout\n', '2 disk full\n1 timeout\n', False, 1),
            ('2\nINFO ok\nWARN slow\n', 'NO ERRORS\n', False, 1),
            ('5\nERROR   db down  \nERROR db down\nerror auth failed\nERROR auth failed\nERROR auth failed\n',
             '3 auth failed\n2 db down\n',
             True,
             2),
            ('3\nerror b\nERROR a\nError c\n', '1 a\n1 b\n1 c\n', True, 2)],
  'reference_source': 'n = int(input())\n'
                      'counts = {}\n'
                      'for _ in range(n):\n'
                      '    line = input().strip()\n'
                      '    parts = line.split(None, 1)\n'
                      '    if len(parts) < 2:\n'
                      '        continue\n'
                      '    level, message = parts[0], parts[1].strip()\n'
                      '    if level.upper() == "ERROR":\n'
                      '        counts[message] = counts.get(message, 0) + 1\n'
                      'if not counts:\n'
                      '    print("NO ERRORS")\n'
                      'for message, count in sorted(counts.items(), key=lambda item: (-item[1], item[0])):\n'
                      '    print(count, message)\n'},
