 {'technology': 'javascript',
  'topic': 'professional-challenges',
  'kind': 'expert',
  'track': 'professional',
  'name': 'Kth Largest Value',
  'slug': 'js-pro-kth-largest',
  'description': 'Print the k-th largest value. The values are generated: a[0] = seed, a[i] = (a[i-1] * 1103515245 + 12345) mod '
                 '2147483648. In JavaScript, compute it with BigInt or split the multiplication, because the product exceeds 2^53. Take '
                 'each value mod 1,000,000.',
  'input_format': 'One line: n k seed.',
  'output_format': 'Print the k-th largest value.',
  'constraints': '1 ≤ k ≤ n ≤ 200,000.',
  'examples': [{'input': '6 2 1', 'output': '824084'}],
  'language': 'javascript',
  'language_id': 63,
  'difficulty': 'Hard',
  'order': 4,
  'starter': "const fs = require('fs');\nconst input = fs.readFileSync(0, 'utf8').split('\\n');\n// Write your solution below\n",
  'tests': [('6 2 1\n', '824084\n', False, 1),
            ('1 1 7\n', '7\n', False, 1),
            ('1000 1000 3\n', '3\n', True, 1),
            ('200000 12345 9\n', '937974\n', True, 3),
            ('150000 1 2\n', '999998\n', True, 2)],
  'reference_source': "const fs = require('fs');\n"
                      "const input = fs.readFileSync(0, 'utf8').split('\\n');\n"
                      'function next(v) { return Number((BigInt(v) * 1103515245n + 12345n) % 2147483648n); }\n'
                      'const [n, k, seed] = input[0].trim().split(/\\s+/).map(Number);\n'
                      'const values = new Array(n);\n'
                      'let v = seed;\n'
                      'for (let i = 0; i < n; i++) { values[i] = v % 1000000; v = next(v); }\n'
                      'values.sort((a, b) => b - a);\n'
                      'console.log(values[k - 1]);\n'},
 {'technology': 'javascript',
  'topic': 'professional-challenges',
  'kind': 'expert',
  'track': 'professional',
  'name': 'Edit Distance',
  'slug': 'js-pro-edit-distance',
  'description': 'Print the minimum number of single-character inserts, deletes or replacements that turn word a into word b.',
  'input_format': 'Two lines: a, then b.',
  'output_format': 'Print the edit distance.',
  'constraints': '0 ≤ |a|, |b| ≤ 2,000.',
  'examples': [{'input': 'horse\nros', 'output': '3'}],
  'language': 'javascript',
  'language_id': 63,
  'difficulty': 'Hard',
  'order': 5,
  'starter': "const fs = require('fs');\nconst input = fs.readFileSync(0, 'utf8').split('\\n');\n// Write your solution below\n",
  'tests': [('horse\nros\n', '3\n', False, 1),
            ('abc\nabc\n', '0\n', False, 1),
            ('\nabc\n', '3\n', True, 1),
            ('intention\nexecution\n', '5\n', True, 2),
            ('\n'
             '\n',
             '926\n',
             True,
             3)],
  'reference_source': "const fs = require('fs');\n"
                      "const input = fs.readFileSync(0, 'utf8').split('\\n');\n"
                      "const a = (input[0] || '').trim(), b = (input[1] || '').trim();\n"
                      'let prev = [];\n'
                      'for (let j = 0; j <= b.length; j++) prev.push(j);\n'
                      'for (let i = 1; i <= a.length; i++) {\n'
                      '  const cur = [i];\n'
                      '  for (let j = 1; j <= b.length; j++) {\n'
                      '    cur.push(Math.min(prev[j] + 1, cur[j - 1] + 1, prev[j - 1] + (a[i - 1] === b[j - 1] ? 0 : 1)));\n'
                      '  }\n'
                      '  prev = cur;\n'
                      '}\n'
                      'console.log(prev[b.length]);\n'},
