 {'technology': 'javascript',
  'topic': 'professional-challenges',
  'kind': 'expert',
  'track': 'professional',
  'name': 'Maximum Subarray Sum',
  'slug': 'js-pro-max-subarray',
  'description': 'Print the largest sum of a non-empty contiguous subarray. The values are generated: a[0] = seed, a[i] = (a[i-1] * '
                 '1103515245 + 12345) mod 2147483648. In JavaScript, compute it with BigInt or split the multiplication, because the '
                 'product exceeds 2^53. Use (value mod 2001) - 1000 so values range from -1000 to 1000.',
  'input_format': 'One line: n seed.',
  'output_format': 'Print the maximum subarray sum.',
  'constraints': '1 ≤ n ≤ 200,000. O(n²) runs out of time.',
  'examples': [{'input': '8 1', 'output': '117'}],
  'language': 'javascript',
  'language_id': 63,
  'difficulty': 'Hard',
  'order': 9,
  'starter': "const fs = require('fs');\nconst input = fs.readFileSync(0, 'utf8').split('\\n');\n// Write your solution below\n",
  'tests': [('8 1\n', '117\n', False, 1),
            ('1 4\n', '-996\n', False, 1),
            ('1000 9\n', '11030\n', True, 1),
            ('200000 77\n', '290945\n', True, 3),
            ('120000 5\n', '241732\n', True, 2)],
  'reference_source': "const fs = require('fs');\n"
                      "const input = fs.readFileSync(0, 'utf8').split('\\n');\n"
                      'function next(v) { return Number((BigInt(v) * 1103515245n + 12345n) % 2147483648n); }\n'
                      'const [n, seed] = input[0].trim().split(/\\s+/).map(Number);\n'
                      'let v = seed, best = -Infinity, cur = 0;\n'
                      'for (let i = 0; i < n; i++) {\n'
                      '  const x = (v % 2001) - 1000;\n'
                      '  cur = Math.max(x, cur + x);\n'
                      '  best = Math.max(best, cur);\n'
                      '  v = next(v);\n'
                      '}\n'
                      'console.log(best);\n'},
 {'technology': 'javascript',
  'topic': 'professional-challenges',
  'kind': 'expert',
  'track': 'professional',
  'name': 'Word Break',
  'slug': 'js-pro-word-break',
  'description': 'Can the text be split into a sequence of dictionary words (words may repeat)?',
  'input_format': 'First line: the dictionary words, space-separated. Second line: the text.',
  'output_format': 'Print YES or NO.',
  'constraints': 'Up to 1,000 dictionary words of length ≤ 20; text length ≤ 5,000.',
  'examples': [{'input': 'leet code\nleetcode', 'output': 'YES'}],
  'language': 'javascript',
  'language_id': 63,
  'difficulty': 'Hard',
  'order': 10,
  'starter': "const fs = require('fs');\nconst input = fs.readFileSync(0, 'utf8').split('\\n');\n// Write your solution below\n",
  'tests': [('leet code\nleetcode\n', 'YES\n', False, 1),
            ('cats dog sand and cat\ncatsandog\n', 'NO\n', False, 1),
            ('a aa aaa\naaaaaaa\n', 'YES\n', True, 2),
            ('ab abc cd\n'
             '\n',
             'YES\n',
             True,
             3),
            ('a b\n'
             '\n',
             'NO\n',
             True,
             2)],
  'reference_source': "const fs = require('fs');\n"
                      "const input = fs.readFileSync(0, 'utf8').split('\\n');\n"
                      "const dict = new Set((input[0] || '').trim().split(/\\s+/).filter(Boolean));\n"
                      "const s = (input[1] || '').trim();\n"
                      'let longest = 0;\n'
                      'dict.forEach((w) => { if (w.length > longest) longest = w.length; });\n'
                      'const ok = new Array(s.length + 1).fill(false);\n'
                      'ok[0] = true;\n'
                      'for (let i = 1; i <= s.length; i++) {\n'
                      '  for (let len = 1; len <= Math.min(longest, i); len++) {\n'
                      '    if (ok[i - len] && dict.has(s.slice(i - len, i))) { ok[i] = true; break; }\n'
                      '  }\n'
                      '}\n'
                      "console.log(ok[s.length] ? 'YES' : 'NO');\n"},
 {'technology': 'javascript',
  'topic': 'professional-real-world-tasks',
  'kind': 'real_world',
  'track': 'professional',
  'name': 'Fix the Cart Total',
  'slug': 'js-pro-fix-cart-total',
  'description': "A shop's checkout shows totals like 0.30000000000000004 and sometimes joins prices as text. Fix the cart total: add "
                 'quantity × price for every line and print the total in rupees with exactly two decimals.',
  'input_format': 'First line n. Next n lines: item quantity price (price has up to 2 decimals).',
  'output_format': 'Print the total with two decimals.',
  'constraints': '1 ≤ n ≤ 1,000, 1 ≤ quantity ≤ 1,000, 0 ≤ price ≤ 100,000.',
  'examples': [{'input': '2\npen 1 0.10\ncap 2 0.10', 'output': '0.30'}],
  'language': 'javascript',
  'language_id': 63,
  'difficulty': 'Hard',
  'order': 11,
  'starter': "const fs = require('fs');\n"
             "const input = fs.readFileSync(0, 'utf8').split('\\n');\n"
             'const n = Number(input[0]);\n'
             'let total = 0;\n'
             'for (let i = 1; i <= n; i++) {\n'
             "  const p = input[i].split(' ');\n"
             '  total += p[1] * p[2];\n'
             '  total = total.toFixed(2);\n'
             '}\n'
             'console.log(total);\n',
  'tests': [('2\npen 1 0.10\ncap 2 0.10\n', '0.30\n', False, 1),
            ('1\nbook 3 99.99\n', '299.97\n', False, 1),
            ('3\na 1 0.07\nb 10 0.01\nc 1 0\n', '0.17\n', True, 2),
            ('4\nx 999 100000.00\ny 1 0.01\nz 3 33.33\nw 7 1.05\n', '99900107.35\n', True, 2)],
  'reference_source': "const fs = require('fs');\n"
                      "const input = fs.readFileSync(0, 'utf8').split('\\n');\n"
                      'const n = Number(input[0]);\n'
                      'let paise = 0;\n'
                      'for (let i = 1; i <= n; i++) {\n'
                      '  const p = input[i].trim().split(/\\s+/);\n'
                      '  paise += Number(p[1]) * Math.round(Number(p[2]) * 100);\n'
                      '}\n'
                      'console.log((paise / 100).toFixed(2));\n'},
