 {'technology': 'javascript',
  'topic': 'professional-real-world-tasks',
  'kind': 'real_world',
  'track': 'professional',
  'name': 'Fix the Settings Merge',
  'slug': 'js-pro-fix-settings-merge',
  'description': 'The app merges user settings over the defaults, but nested sections lose their other keys. Deep-merge the second JSON '
                 'object into the first (objects merge key by key; anything else is replaced) and print the result as JSON with keys '
                 'sorted at every level.',
  'input_format': 'Two lines: defaults JSON, then user JSON.',
  'output_format': 'Print the merged JSON (no spaces), keys sorted.',
  'constraints': 'Each JSON ≤ 50 KB.',
  'examples': [{'input': '{"theme":{"color":"blue","font":12},"lang":"en"}\n{"theme":{"font":14}}',
                'output': '{"lang":"en","theme":{"color":"blue","font":14}}'}],
  'language': 'javascript',
  'language_id': 63,
  'difficulty': 'Hard',
  'order': 14,
  'starter': "const fs = require('fs');\n"
             "const input = fs.readFileSync(0, 'utf8').split('\\n');\n"
             'const base = JSON.parse(input[0]);\n'
             'const user = JSON.parse(input[1]);\n'
             'const merged = Object.assign({}, base, user);\n'
             'console.log(JSON.stringify(merged));\n',
  'tests': [('{"theme":{"color":"blue","font":12},"lang":"en"}\n{"theme":{"font":14}}\n',
             '{"lang":"en","theme":{"color":"blue","font":14}}\n',
             False,
             1),
            ('{"a":1}\n{}\n', '{"a":1}\n', False, 1),
            ('{"x":{"y":{"z":1,"w":2}},"list":[1,2]}\n{"x":{"y":{"z":5}},"list":[3]}\n', '{"list":[3],"x":{"y":{"w":2,"z":5}}}\n', True, 2),
            ('{"a":{"b":1},"c":2}\n{"a":3,"d":{"e":null}}\n', '{"a":3,"c":2,"d":{"e":null}}\n', True, 2)],
  'reference_source': "const fs = require('fs');\n"
                      "const input = fs.readFileSync(0, 'utf8').split('\\n');\n"
                      'const base = JSON.parse(input[0]);\n'
                      'const user = JSON.parse(input[1]);\n'
                      "function isObj(x) { return x !== null && typeof x === 'object' && !Array.isArray(x); }\n"
                      'function merge(a, b) {\n'
                      '  const out = Object.assign({}, a);\n'
                      '  Object.keys(b).forEach((k) => { out[k] = isObj(a[k]) && isObj(b[k]) ? merge(a[k], b[k]) : b[k]; });\n'
                      '  return out;\n'
                      '}\n'
                      'function sorted(x) {\n'
                      '  if (Array.isArray(x)) return x.map(sorted);\n'
                      '  if (!isObj(x)) return x;\n'
                      '  const out = {};\n'
                      '  Object.keys(x).sort().forEach((k) => { out[k] = sorted(x[k]); });\n'
                      '  return out;\n'
                      '}\n'
                      'console.log(JSON.stringify(sorted(merge(base, user))));\n'},
